  vocab=[N("v-invoering","invoering","introdução|implementação","de"), N("v-afschaffing","afschaffing","abolição|extinção","de"),
         N("v-verhoging","verhoging","aumento","de","verhogingen"), X("v-verhogen","verhogen","aumentar","verb"), X("v-afschaffen","afschaffen","abolir|acabar com","verb")],
  ex=[("De invoering van de nieuwe regels is uitgesteld.","A introdução das novas regras foi adiada."),("Veel mensen zijn tegen de afschaffing van de basisbeurs.","Muitas pessoas são contra a extinção da bolsa básica."),("Een verhoging van de huur met 5%.","Um aumento da renda de 5%."),("De regering wil die regel afschaffen.","O governo quer abolir essa regra.")],
